-- Universe Civilization: Empire at Wars
-- Seed 90 construction and factory designs: 10 classes × 9 types.
ON DUPLICATE KEY UPDATE
  name=VALUES(name), display_name=VALUES(display_name), category=VALUES(category), max_level=VALUES(max_level),
  base_time_seconds=VALUES(base_time_seconds), base_metal=VALUES(base_metal), base_crystal=VALUES(base_crystal),
  base_naquadah=VALUES(base_naquadah), base_energy=VALUES(base_energy), effect_key=VALUES(effect_key),
  effect_per_level=VALUES(effect_per_level), prerequisite_key=VALUES(prerequisite_key), prerequisite_level=VALUES(prerequisite_level),
  description=VALUES(description), is_active=VALUES(is_active), building_class=VALUES(building_class), buildable_on=VALUES(buildable_on),
  field_size=VALUES(field_size), base_power_output=VALUES(base_power_output), base_power_consumption=VALUES(base_power_consumption), placement_rule=VALUES(placement_rule);
